\begin{ex}%[7H4H4]
Cho $\Delta{ABC}$, ${M}$ kà trung điểm của ${BC}$. Trên tia đối của tia ${MA}$ lấy điểm ${E}$ sao cho $ME=MA$. Chứng minh 

  a) $\Delta{ABM}=\Delta{ECM} $ 

b) $AB=CE$ và $AC//BE$
\loigiai{
\begin{tikzpicture}
  % Vẽ các điểm A, B, C
\coordinate [label=above: {$A$}] (A) at (0, 4);
\coordinate [label=left:{$B$}] (B) at (-1, 0);
\coordinate [label=right:{$C$}] (C) at (3, 0);
\coordinate [label=below left:{$M$}] (M) at (1, 0);
\coordinate [label=below left:{$E$}] (E) at (2, -4);
% Vẽ các cạnh của tam giác
\draw (A) -- (B) -- (C) -- cycle;
  \draw
 ($(M)!0.7!(E)$)node[rotate=90]{$/$} ($(M)!0.5!(A)$)node[rotate=90]{$/$};
 \draw
 ($(M)!0.7!(B)$)node[rotate=40]{$//$} ($(M)!0.5!(C)$)node[rotate=40]{$//$};
% Vẽ đoạn thẳng AE
\draw (A) -- (M)--(E) ;

\end{tikzpicture}
a) $\Delta{ABM}=\Delta{ECM} $ (c.g.c)\\
b) $AB=CE$ (Cặp cạnh tương ứng)\\
Tương tự ta có $\Delta{AMC}= \Delta{EMB} $ suy ra $\widehat{ACM} =\widehat{EBM}$ suy ra $BE//AC$
}\end{ex}

